/// A decoded client packet.
#[derive(Clone, Debug)]
pub enum ClientMsg {
    BlockRequest(ClientMacroBlockRequest),
    InitialDataRequest,
    ObjectCreate { ty: u8, items: Option<PV> },
    ObjectUpdate { ty: u8, items: Option<PV> },
    ObjectRemove { ty: u8, items: Option<PV> },
    ObjectCreationDataUpdate { ty: u8, items: Option<PV> },
    BlockRemovalNotification { macro_index: u32 },
    UniqueIdRequest,
    FillRequest { payload: Vec<u8> },
    RemoveRequest { payload: Vec<u8> },
    RemoveBackWallRequest { payload: Vec<u8> },
    PickupRequest { requester: u64, ids: Vec<u64> },
    FreeblockCreation { payload: Vec<u8> },
    PlaceWorkbench { payload: Vec<u8> },
    PlaceInteractionObject { payload: Vec<u8> },
    Heartbeat { payload: Vec<u8> },
    HeartbeatRequestOld,
    HeartbeatRequestWithRules { payload: Vec<u8> },
    Paint { payload: Vec<u8> },
    Gather { payload: Vec<u8>, original: Vec<u8> },
    Projectile { payload: Vec<u8>, original: Vec<u8> },
    Tip { payload: Vec<u8>, original: Vec<u8> },
    BlockheadDamage { payload: Vec<u8> },
    ElectricityPath { payload: Vec<u8> },
    ZoomRequest { player_id: Option<String>, cycle_index: i32 },
    ClientBlockheads { payload: Vec<u8> },
    ClientBlockheadInventory { blockhead_id: u64, data: Vec<u8> },
    TradeTransaction { dict: Option<PV> },
    PaintingDataRequest { id: u64 },
    WelcomeMessageSet { dict: Option<PV> },
    WelcomeMessageGet,
    ReportUser { dict: Option<PV> },
    PasswordChange { new_password: Option<String> },
    PrivacyChange { privacy: Option<String> },
    OwnershipSignPlayerListRequest,
    PortalChestTransaction { raw8: [u8; 8], id: u16 },
    PortalChestTransactionResend { raw8: [u8; 8], id: u16 },
    UpdateCustomRule { dict: Option<PV>, original: Vec<u8> },
    FoundItemsOld { payload: Vec<u8> },
    FoundItemsV2 { ranges: Vec<(u32, u32)> },
    DynamicObjectRemovalRequest { blockhead_id: u64, object_id: u64 },
    RepairTile { world_index: i32 },
    Chat { dict: Option<PV> },
    PlayerInformation { payload: Vec<u8> },
}

/// The exception a nil 0x24 chat plist ends in (`[chatHistory addObject:nil]` path, observed exit 0 with this text).
/// Raised by the server's chat flow, not by the decoder.
pub fn chat_nil_exception() -> Malformed {
    Malformed::Exception { name: "NSInvalidArgumentException", reason: "Tried to insert nil to array".to_string() }
}

fn raw8(payload: &[u8]) -> WireResult<([u8; 8], u16)> {
    if payload.len() < 8 {
        return Err(Malformed::get_bytes_range8(payload.len()));
    }
    let r: [u8; 8] = payload[..8].try_into().unwrap();
    Ok((r, u16::from_le_bytes([r[0], r[1]])))
}
fn str_key(d: &Option<PV>, k: &str) -> Option<String> {
    d.as_ref()?.object_for_key(k)?.as_str().map(|s| s.to_string())
}

/// Decode a client packet (type byte first). `Ok(None)` = unknown type / empty packet (ignored);
/// `Err` per. Applies no gate or permission check.
pub fn decode_client_packet(packet: &[u8]) -> WireResult<Option<ClientMsg>> {
    let Some((ty, p)) = codec::split_type(packet) else {
        return Ok(None);
    };
    let pv = || p.to_vec();
    let orig = || packet.to_vec();
    let m = match ty {
        t::CLIENT_BLOCK_REQUEST => ClientMsg::BlockRequest(decode_or0(p)),
        t::CLIENT_INITIAL_DATA_REQUEST => ClientMsg::InitialDataRequest,
        t::CLIENT_DYNAMIC_OBJECT_CREATE
        | t::CLIENT_DYNAMIC_OBJECT_UPDATE
        | t::CLIENT_DYNAMIC_OBJECT_REMOVE
        | t::CLIENT_DYNAMIC_OBJECT_CREATION_DATA_UPDATE => {
            if packet.len() < 2 {
                return Err(Malformed::malloc());
            }
            let oty = packet[1];
            let items = gz_plist_from(&packet[2..]);
            match ty {
                t::CLIENT_DYNAMIC_OBJECT_CREATE => ClientMsg::ObjectCreate { ty: oty, items },
                t::CLIENT_DYNAMIC_OBJECT_UPDATE => ClientMsg::ObjectUpdate { ty: oty, items },
                t::CLIENT_DYNAMIC_OBJECT_REMOVE => ClientMsg::ObjectRemove { ty: oty, items },
                _ => ClientMsg::ObjectCreationDataUpdate { ty: oty, items },
            }
        }
        t::CLIENT_BLOCK_REMOVAL_NOTIFICATION => {
            ClientMsg::BlockRemovalNotification { macro_index: Rd::new(p).u32_or0() }
        }
        t::CLIENT_UNIQUE_ID_REQUEST => ClientMsg::UniqueIdRequest,
        t::CLIENT_FILL_REQUEST => ClientMsg::FillRequest { payload: pv() },
        t::CLIENT_REMOVE_REQUEST => ClientMsg::RemoveRequest { payload: pv() },
        t::CLIENT_REMOVE_BACK_WALL_REQUEST => ClientMsg::RemoveBackWallRequest { payload: pv() },
        t::CLIENT_PICKUP_REQUEST => {
            if p.len() < 8 {
                return Err(Malformed::get_bytes_range8(p.len()));
            }
            let mut r = Rd::new(p);
            let requester = r.u64_or0();
            let n = (p.len() >> 3) - 1;
            let ids = (0..n).map(|_| r.u64_or0()).collect();
            ClientMsg::PickupRequest { requester, ids }
        }
        t::CLIENT_FREEBLOCK_CREATION_REQUEST => ClientMsg::FreeblockCreation { payload: pv() },
        t::CLIENT_PLACE_WORKBENCH_REQUEST => {
            if p.len() < 16 {
                return Err(Malformed::range_too_great());
            }
            ClientMsg::PlaceWorkbench { payload: pv() }
        }
        t::CLIENT_PLACE_INTERACTION_OBJECT_REQUEST => {
            if p.len() < 8 {
                return Err(Malformed::range_too_great());
            }
            ClientMsg::PlaceInteractionObject { payload: pv() }
        }
        t::SERVER_WORLD_HEARTBEAT => ClientMsg::Heartbeat { payload: pv() },
        t::CLIENT_WORLD_HEARTBEAT_REQUEST => ClientMsg::HeartbeatRequestOld,
        t::CLIENT_WORLD_HEARTBEAT_REQUEST_WITH_CUSTOM_RULES => ClientMsg::HeartbeatRequestWithRules { payload: pv() },
        t::CLIENT_PAINT_REQUEST => ClientMsg::Paint { payload: pv() },
        t::GATHER_NOTIFICATION => ClientMsg::Gather { payload: pv(), original: orig() },
        t::CLIENT_PROJECTILE_REQUEST => ClientMsg::Projectile { payload: pv(), original: orig() },
        t::TIP_NOTIFICATION => ClientMsg::Tip { payload: pv(), original: orig() },
        t::CLIENT_BLOCKHEAD_DAMAGE_REQUEST => ClientMsg::BlockheadDamage { payload: pv() },
        t::ELECTRICITY_PATH => {
            if p.len() < 8 {
                return Err(Malformed::range_too_great());
            }
            ClientMsg::ElectricityPath { payload: pv() }
        }
        t::ZOOM_LOCATION_REQUEST => {
            let d = plist_from(p);
            let player_id = str_key(&d, "playerID");
            let cycle_index =
                d.as_ref().and_then(|d| d.object_for_key("cycleIndex")).map(|v| v.int_value()).unwrap_or(0);
            ClientMsg::ZoomRequest { player_id, cycle_index }
        }
        t::CLIENT_PLAYER_INFORMATION => ClientMsg::PlayerInformation { payload: pv() },
        t::CLIENT_BLOCKHEADS => ClientMsg::ClientBlockheads { payload: pv() },
        t::CLIENT_BLOCKHEAD_INVENTORY => {
            if packet.len() < 9 {
                return Err(Malformed::malloc());
            }
            ClientMsg::ClientBlockheadInventory { blockhead_id: Rd::new(p).u64_or0(), data: packet[9..].to_vec() }
        }
        // Note: says the decoder returns the
        // `NSInvalidArgumentException` for a nil chat plist, but show the original raises later
        // (after the cloud curse-word step) inside the chat flow. The decoder therefore passes nil on as `dict: None`
        // and the server raises `chat_nil_exception()` at the point.
        t::CHAT_MESSAGE => ClientMsg::Chat { dict: plist_from_mutable(p) },
        t::CLIENT_TRADE_TRANSACTION => ClientMsg::TradeTransaction { dict: gz_plist_from(p) },
        t::CLIENT_REQUEST_PAINTING_DATA => ClientMsg::PaintingDataRequest { id: Rd::new(p).u64_or0() },
        t::CLIENT_WELCOME_MESSAGE_SET_REQUEST => ClientMsg::WelcomeMessageSet { dict: gz_plist_from(p) },
        t::CLIENT_WELCOME_MESSAGE_GET_REQUEST => ClientMsg::WelcomeMessageGet,
        t::CLIENT_REPORT_USER => ClientMsg::ReportUser { dict: gz_plist_from(p) },
        t::CLIENT_PASSWORD_CHANGE_REQUEST => {
            let new_password = if packet.len() == 1 { None } else { str_key(&plist_from(p), "newServerPassword") };
            ClientMsg::PasswordChange { new_password }
        }
        t::CLIENT_PRIVACY_CHANGE_REQUEST => {
            let privacy = if packet.len() < 2 { None } else { str_key(&plist_from(p), "privacySetting") };
            ClientMsg::PrivacyChange { privacy }
        }
        t::CLIENT_OWNERSHIP_SIGN_PLAYER_LIST_REQUEST => ClientMsg::OwnershipSignPlayerListRequest,
        t::CLIENT_PORTAL_CHEST_TRANSACTION => {
            let (raw8, id) = raw8(p)?;
            ClientMsg::PortalChestTransaction { raw8, id }
        }
        t::CLIENT_PORTAL_CHEST_TRANSACTION_RESEND => {
            let (raw8, id) = raw8(p)?;
            ClientMsg::PortalChestTransactionResend { raw8, id }
        }
        t::CLIENT_UPDATE_CUSTOM_RULE => ClientMsg::UpdateCustomRule { dict: gz_plist_from(p), original: orig() },
        t::CLIENT_FOUND_ITEM_LIST_CHANGED_OLD => ClientMsg::FoundItemsOld { payload: pv() },
        t::CLIENT_FOUND_ITEM_LIST_CHANGED_V2 => ClientMsg::FoundItemsV2 { ranges: index_set_decode(p) },
        t::CLIENT_DYNAMIC_OBJECT_REMOVAL_REQUEST => {
            let mut r = Rd::new(p);
            let blockhead_id = r.u64_or0();
            let object_id = r.u64_or0();
            ClientMsg::DynamicObjectRemovalRequest { blockhead_id, object_id }
        }
        t::CLIENT_REPAIR_TILE => ClientMsg::RepairTile { world_index: Rd::new(p).u64_or0() as u32 as i32 },
        _ => return Ok(None),
    };
    Ok(Some(m))
}

// ------------------------------------------------------------------------------------------------------------
// server -> client decoder (bh_testclient)
// ------------------------------------------------------------------------------------------------------------

/// A decoded server packet.
#[derive(Clone, Debug)]
pub enum ServerMsg {
    Contact { version: u8, plist: Option<PV> },
    Rejection { reason: u8, extra: Option<PV> },
    Summary(Option<PV>),
    PlayerList(Option<PV>),
    Chat(Option<PV>),
    ChatHistory(Option<PV>),
    Heartbeat(WorldHeartbeat),
    InitialData { food_types: [i32; 31], plist: Option<PV> },
    UniqueId(u64),
    PickupReply { accepted: bool, requester: u64, ids: Vec<u64> },
    ZoomResponse(Option<(i32, i32)>),
    Block(super::block_wire::BlockMsg),
    BlockNotLoaded { index: u64, index32: u32 },
    LightBlock(super::block_wire::LightBlockMsg),
    Batch(super::object_batches::Batch),
    AdminOrModChanged { x: i32, y: i32 },
    PriceOffsets(Option<PV>),
    PaintingData { id: u64, image: Vec<u8> },
    ChestInventory { id: u64, inventory: Vec<u8> },
    Welcome(Option<PV>),
    OwnershipSignPlayerList(Option<PV>),
    OwnershipSignModified(Option<PV>),
    PortalChestAck { raw8: [u8; 8], id: u16 },
    PortalChestNotSaved { raw8: [u8; 8], id: u16 },
    ClearChat,
    ToggleRepairMode(bool),
    Gather(GatherNetRequest),
    Projectile(ProjectileNetRequest),
    Damage(BlockheadDamageNetRequest),
    ElectricityPath { header: ElectricityHeader, path: Vec<ElectricityPathIndex> },
    Tip(String),
    Unknown { ty: u8, payload: Vec<u8> },
}

/// Decode a server -> client packet (test client). Never fails for known types; short fixed structs are
/// zero-filled.
pub fn decode_server_packet(packet: &[u8]) -> WireResult<ServerMsg> {
    let Some((ty, p)) = codec::split_type(packet) else {
        return Err(Malformed::Ignore);
    };
    use super::{block_wire, object_batches};
    Ok(match ty {
        t::SERVER_INITIAL_CONTACT => ServerMsg::Contact {
            version: p.first().copied().unwrap_or(0),
            plist: plist_from(p.get(1..).unwrap_or(&[])),
        },
        t::SERVER_CONNECTION_REJECTION => ServerMsg::Rejection {
            reason: p.first().copied().unwrap_or(0),
            extra: plist_from(p.get(1..).unwrap_or(&[])),
        },
        t::WORLD_SUMMARY => ServerMsg::Summary(gz_plist_from(p)),
        t::SERVER_PLAYER_LIST_CHANGED_NOTIFICATION => ServerMsg::PlayerList(plist_from(p)),
        t::CHAT_MESSAGE => ServerMsg::Chat(plist_from(p)),
        t::CHAT_MESSAGE_HISTORY => ServerMsg::ChatHistory(plist_from(p)),
        t::SERVER_WORLD_HEARTBEAT => ServerMsg::Heartbeat(decode_or0(p)),
        t::SERVER_INITIAL_DATA_REPLY => {
            let mut r = Rd::new(p);
            let mut f = [0i32; 31];
            for x in f.iter_mut() {
                *x = r.i32_or0();
            }
            ServerMsg::InitialData { food_types: f, plist: plist_from(r.rest()) }
        }
        t::SERVER_UNIQUE_ID_REPLY => ServerMsg::UniqueId(Rd::new(p).u64_or0()),
        t::SERVER_PICKUP_REPLY => {
            let h: PickupHeader = decode_or0(packet);
            let mut r = Rd::new(packet.get(16..).unwrap_or(&[]));
            let mut ids = Vec::new();
            while r.remaining() >= 8 {
                ids.push(r.u64_or0());
            }
            ServerMsg::PickupReply { accepted: h.accepted != 0, requester: h.blockhead_unique_id, ids }
        }
        t::ZOOM_LOCATION_RESPONSE => {
            let mut r = Rd::new(p);
            ServerMsg::ZoomResponse(match (r.i32(), r.i32()) {
                (Some(x), Some(y)) => Some((x, y)),
                _ => None,
            })
        }
        t::SERVER_BLOCK => match block_wire::decode_server_block(p) {
            Some(b) => ServerMsg::Block(b),
            None => ServerMsg::Unknown { ty, payload: p.to_vec() },
        },
        t::SERVER_BLOCK_NOT_LOADED => match block_wire::decode_block_not_loaded(p) {
            Some((index, index32)) => ServerMsg::BlockNotLoaded { index, index32 },
            None => ServerMsg::Unknown { ty, payload: p.to_vec() },
        },
        t::SERVER_LIGHT_BLOCK => match block_wire::decode_light_block(p) {
            Some(b) => ServerMsg::LightBlock(b),
            None => ServerMsg::Unknown { ty, payload: p.to_vec() },
        },
        t::SERVER_DYNAMIC_OBJECT_CREATE
        | t::SERVER_DYNAMIC_OBJECT_UPDATE
        | t::SERVER_DYNAMIC_OBJECT_REMOVE
        | t::SERVER_DYNAMIC_OBJECT_CREATION_DATA_UPDATE => match object_batches::decode_batch(packet)? {
            Some(b) => ServerMsg::Batch(b),
            None => ServerMsg::Unknown { ty, payload: p.to_vec() },
        },
        t::SERVER_ADMIN_OR_MOD_CHANGED => {
            let mut r = Rd::new(p);
            ServerMsg::AdminOrModChanged { x: r.i32_or0(), y: r.i32_or0() }
        }
        t::SERVER_WORLD_PRICE_OFFSET_LIST => ServerMsg::PriceOffsets(gz_plist_from(p)),
        t::SERVER_PAINTING_DATA => {
            let mut r = Rd::new(p);
            ServerMsg::PaintingData { id: r.u64_or0(), image: r.rest().to_vec() }
        }
        t::SERVER_CHEST_INVENTORY_DATA => {
            let mut r = Rd::new(p);
            ServerMsg::ChestInventory { id: r.u64_or0(), inventory: r.rest().to_vec() }
        }
        t::SERVER_WELCOME_MESSAGE => ServerMsg::Welcome(plist_from(p)),
        t::SERVER_OWNERSHIP_SIGN_PLAYER_LIST_DATA => ServerMsg::OwnershipSignPlayerList(plist_from(p)),
        t::SERVER_OWNERSHIP_SIGN_MODIFIED_NOTIFATION => ServerMsg::OwnershipSignModified(gz_plist_from(p)),
        t::SERVER_PORTAL_CHEST_ACK | t::SERVER_PORTAL_CHEST_NOT_SAVED => {
            let mut b = [0u8; 8];
            let n = p.len().min(8);
            b[..n].copy_from_slice(&p[..n]);
            let id = u16::from_le_bytes([b[0], b[1]]);
            if ty == t::SERVER_PORTAL_CHEST_ACK {
                ServerMsg::PortalChestAck { raw8: b, id }
            } else {
                ServerMsg::PortalChestNotSaved { raw8: b, id }
            }
        }
        t::SERVER_CLEAR_CHAT => ServerMsg::ClearChat,
        t::SERVER_TOGGLE_REPAIR_MODE => ServerMsg::ToggleRepairMode(p.first().copied().unwrap_or(0) != 0),
        t::GATHER_NOTIFICATION => ServerMsg::Gather(decode_or0(p)),
        t::CLIENT_PROJECTILE_REQUEST => ServerMsg::Projectile(decode_or0(p)),
        t::CLIENT_BLOCKHEAD_DAMAGE_REQUEST => ServerMsg::Damage(decode_or0(p)),
        t::ELECTRICITY_PATH => {
            let header: ElectricityHeader = decode_or0(p);
            let raw = gunz(p.get(8..).unwrap_or(&[])).unwrap_or_default();
            let path = raw.chunks_exact(8).map(ElectricityPathIndex::read_le).collect();
            ServerMsg::ElectricityPath { header, path }
        }
        t::TIP_NOTIFICATION => ServerMsg::Tip(String::from_utf8_lossy(p).into_owned()),
        _ => ServerMsg::Unknown { ty, payload: p.to_vec() },
    })
}

#[cfg(test)]
mod tests {
    use super::super::block_wire::*;
    use super::super::object_batches::*;
    use super::*;
    use crate::types::net_types::{NetDataType, ServerConnectionRejection as R};

    #[test]
    fn constants_match_types() {
        assert_eq!(t::WORLD_SUMMARY, NetDataType::BHNDT_WORLD_SUMMARY.as_byte());
        assert_eq!(t::CLIENT_FOUND_ITEM_LIST_CHANGED_V2, 0x4c);
        assert_eq!(t::SERVER_BLOCK, NetDataType::BHNDT_SERVER_BLOCK.as_byte());
        assert_eq!(t::CLIENT_REPAIR_TILE, NetDataType::BHNDT_CLIENT_REPAIR_TILE.as_byte());
        assert_eq!(codec::reject::NO_CREDIT as u32, R::SERVER_CONNECTION_REJECTION_NO_CREDIT.raw());
        assert_eq!(codec::reject::STILL_LOADING as u32, R::SERVER_CONNECTION_REJECTION_STILL_LOADING.raw());
        assert_eq!(codec::reject::USER_LOGGED_IN as u32, R::SERVER_CONNECTION_REJECTION_USER_LOGGED_IN.raw());
    }

    #[test]
    fn struct_sizes() {
        assert_eq!(FillNetRequest::SIZE, 16);
        assert_eq!(RemoveNetRequest::SIZE, 0x18);
        assert_eq!(PaintNetRequest::SIZE, 0x18);
        assert_eq!(RemoveBackWallNetRequest::SIZE, 16);
        assert_eq!(PlaceWorkbenchNetRequest::SIZE, 16);
        assert_eq!(PlaceInteractionObjectNetRequest::SIZE, 8);
        assert_eq!(GatherNetRequest::SIZE, 16);
        assert_eq!(ProjectileNetRequest::SIZE, 0x14);
        assert_eq!(BlockheadDamageNetRequest::SIZE, 0x10);
        assert_eq!(WorldHeartbeat::SIZE, 16);
        assert_eq!(ElectricityHeader::SIZE, 8);
        assert_eq!(ElectricityPathIndex::SIZE, 8);
        assert_eq!(PortalChestTransaction::SIZE, 8);
        assert_eq!(ClientMacroBlockRequest::SIZE, 8);
        assert_eq!(PickupHeader::SIZE, 16);
        let z: FillNetRequest = decode_or0(&[7]);
        assert_eq!(z.pos_x, 7);
        assert_eq!(z.pos_y, 0);
        let z: GatherNetRequest = decode_or0(&[]);
        assert_eq!(z.to_vec(), vec![0u8; 16]);
    }

    #[test]
    fn gzip_rules() {
        let g = gz(b"hello hello hello");
        assert_eq!(&g[..10], &[0x1f, 0x8b, 8, 0, 0, 0, 0, 0, 0, 3]);
        assert!(gz(&[]).is_empty());
        assert_eq!(gunz(&[]), Some(vec![]));
        assert_eq!(gunz(&g).unwrap(), b"hello hello hello");
        assert_eq!(gunz(&[1, 2, 3, 4, 5]), None);
        assert_eq!(gunz(&g[..g.len() - 5]), None);
        let mut tr = g.clone();
        tr.extend_from_slice(b"garbage");
        assert_eq!(gunz(&tr).unwrap(), b"hello hello hello");
    }

    #[test]
    fn index_set() {
        let b = codec::index_set_encode(&[(1, 3), (7, 1)]);
        let w: Vec<u32> = b.chunks(4).map(|c| u32::from_le_bytes(c.try_into().unwrap())).collect();
        assert_eq!(w, vec![0x171e8f, 1, 3, 7, 1]);
        assert_eq!(index_set_decode(&b), vec![(1, 3), (7, 1)]);
        assert!(index_set_decode(&[1, 2, 3]).is_empty());
        assert!(index_set_decode(&[1, 2, 3, 4, 5, 6, 7, 8]).is_empty());
    }

    /// 0x4c carries the raw `-[NSIndexSet serializedData]` words (no gzip, no plist): the default grant
    /// {0..301, 1024..1095} is `[0x171e8f, 0, 302, 1024, 72]`.
    #[test]
    fn found_items_v2_is_the_raw_serialization() {
        let p = found_items_v2(&[(0, 302), (1024, 72)]);
        let mut want = vec![0x4c];
        for w in [0x171e8fu32, 0, 302, 1024, 72] {
            want.extend_from_slice(&w.to_le_bytes());
        }
        assert_eq!(p, want);
        let Some(ClientMsg::FoundItemsV2 { ranges }) = decode_client_packet(&p).unwrap() else { panic!("not 0x4c") };
        assert_eq!(ranges, vec![(0, 302), (1024, 72)]);
    }

    #[test]
    fn malformed_table() {
        let exc = |p: &[u8]| decode_client_packet(p).unwrap_err();
        for ty in [0x0a, 0x0b, 0x0c, 0x45u8] {
            assert_eq!(exc(&[ty]), Malformed::malloc());
        }
        assert!(matches!(
            decode_client_packet(&[0x0a, 7]).unwrap(),
            Some(ClientMsg::ObjectCreate { ty: 7, items: None })
        ));
        assert_eq!(exc(&[0x12]), Malformed::get_bytes_range8(0));
        assert_eq!(exc(&[0x12, 1, 2, 3]), Malformed::get_bytes_range8(3));
        assert_eq!(exc(&[0x21]), Malformed::malloc());
        assert_eq!(exc(&[0x21, 1, 2, 3, 4, 5, 6, 7]), Malformed::malloc());
        assert_eq!(exc(&[0x3e]), Malformed::get_bytes_range8(0));
        assert_eq!(exc(&[0x40, 1]), Malformed::get_bytes_range8(1));
        assert_eq!(exc(&[0x15]), Malformed::range_too_great());
        assert_eq!(exc(&[0x16]), Malformed::range_too_great());
        assert_eq!(exc(&[0x2c]), Malformed::range_too_great());
        assert!(matches!(decode_client_packet(&[0x24]).unwrap(), Some(ClientMsg::Chat { dict: None })));
        assert_eq!(
            chat_nil_exception(),
            Malformed::Exception { name: "NSInvalidArgumentException", reason: "Tried to insert nil to array".into() }
        );
        assert!(matches!(decode_client_packet(&[0x2e]).unwrap(), Some(ClientMsg::TradeTransaction { dict: None })));
        assert!(matches!(
            decode_client_packet(&[0x1b]).unwrap(),
            Some(ClientMsg::ZoomRequest { player_id: None, cycle_index: 0 })
        ));
        assert!(
            matches!(decode_client_packet(&[0x03]).unwrap(), Some(ClientMsg::BlockRequest(r)) if r.macro_index == 0)
        );
        assert!(matches!(
            decode_client_packet(&[0x0d]).unwrap(),
            Some(ClientMsg::BlockRemovalNotification { macro_index: 0 })
        ));
        assert!(matches!(decode_client_packet(&[0x4b]).unwrap(), Some(ClientMsg::RepairTile { world_index: 0 })));
        assert!(matches!(decode_client_packet(&[0x14]).unwrap(), Some(ClientMsg::FreeblockCreation { .. })));
        assert!(matches!(decode_client_packet(&[0x30]).unwrap(), Some(ClientMsg::PaintingDataRequest { id: 0 })));
        assert!(decode_client_packet(&[0xee]).unwrap().is_none());
        // 0x12 valid
        let pk = pickup_request(5, &[9, 10]);
        let Some(ClientMsg::PickupRequest { requester, ids }) = decode_client_packet(&pk).unwrap() else { panic!() };
        assert_eq!((requester, ids), (5, vec![9, 10]));
        // 0x21
        let mut p = vec![0x21];
        p.extend_from_slice(&7u64.to_le_bytes());
        p.extend_from_slice(b"xy");
        let d = decode_client_packet(&p).unwrap();
        let Some(ClientMsg::ClientBlockheadInventory { blockhead_id, data }) = d else { panic!() };
        assert_eq!((blockhead_id, data), (7, b"xy".to_vec()));
    }

    #[test]
    fn batch_roundtrip() {
        let items = vec![vec![1u8, 2, 3, 4, 5, 6, 7, 8, 9], vec![8u8; 8]];
        let b = encode_batch(BatchKind::Create, 14, &items).unwrap();
        assert_eq!(&b[..2], &[7, 14]);
        let d = decode_batch(&b).unwrap().unwrap();
        assert_eq!(d, Batch { kind: 7, object_type: 14, items: items.clone() });
        let c = encode_client_batch(ClientBatchKind::Remove, 3, &items).unwrap();
        let d = decode_client_packet(&c).unwrap();
        let Some(ClientMsg::ObjectRemove { ty: 3, items: Some(PV::Array(a)) }) = d else { panic!() };
        assert_eq!(a.items.len(), 2);
        assert_eq!(blob_unique_id(&items[0]), Some(0x0807060504030201));
    }

    #[test]
    fn simple_encoders() {
        assert_eq!(rejection(14), vec![0x26, 14]);
        assert_eq!(block_not_loaded(1).len(), 13);
        assert_eq!(zoom_response(None), vec![0x1c]);
        assert_eq!(zoom_response(Some((1, 2))).len(), 9);
        assert_eq!(admin_or_mod_changed(1, 1).len(), 9);
        assert_eq!(portal_chest_ack(0x0102), vec![0x3f, 2, 1, 0, 0, 0, 0, 0, 0]);
        assert_eq!(pickup_reply(false, 1234, &[0x162e]).len(), 24);
        assert_eq!(tip("hi"), vec![0x2d, b'h', b'i']);
        assert_eq!(heartbeat(&WorldHeartbeat::default()).len(), 17);
        assert_eq!(projectile(&ProjectileNetRequest::default()).len(), 21);
        assert_eq!(blockhead_damage(&BlockheadDamageNetRequest::default()).len(), 17);
        assert_eq!(block_request(ClientMacroBlockRequest::default()).len(), 9);
        let e = electricity_path(3, &[ElectricityPathIndex::default(); 2]).unwrap();
        let ServerMsg::ElectricityPath { header, path } = decode_server_packet(&e).unwrap() else { panic!() };
        assert_eq!((header.size, header.path_count, path.len()), (3, 2, 2));
        // pathCount wraps at u16 and only pathCount entries are gzipped.
        let e = electricity_path(1, &vec![ElectricityPathIndex::default(); 65537]).unwrap();
        let ServerMsg::ElectricityPath { header, path } = decode_server_packet(&e).unwrap() else { panic!() };
        assert_eq!((header.path_count, path.len()), (1, 1));
        assert_eq!(block_hash("f5d1278e8109edd94e1e4197e04873b9", 0, 0, false), "1128c17e53085db291e4b0d5393d0420");
    }

    fn dict_of(pairs: Vec<(&str, PV)>) -> PV {
        dict(pairs)
    }

    #[test]
    fn server_packets_round_trip_through_the_decoder() {
        let sm = |p: Vec<u8>| decode_server_packet(&p).unwrap();
        let ServerMsg::Contact { version, plist } = sm(initial_contact(Some("Owner"), true, "w1")) else { panic!() };
        let plist = plist.unwrap();
        assert_eq!(version, PROTOCOL_VERSION);
        assert_eq!(plist.object_for_key("ownerName").unwrap().as_str(), Some("Owner"));
        assert!(plist.object_for_key("requiresPassword").is_some());
        let ServerMsg::Rejection { reason, extra } = sm(rejection(11)) else { panic!() };
        assert_eq!((reason, extra.is_none()), (11, true));
        let ServerMsg::Rejection { reason, extra } = sm(rejection_no_credit("w", "World")) else { panic!() };
        assert_eq!((reason, extra.unwrap().object_for_key("worldName").unwrap().as_str()), (13, Some("World")));
        let entries = [
            PlayerListEntry {
                alias: "A".into(),
                photo: Some(vec![1, 2]),
                player_id: "pa".into(),
                connected: true,
                modk: Some("owner"),
                supermod: Some("mode1"),
            },
            PlayerListEntry {
                alias: "B".into(),
                photo: None,
                player_id: "pb".into(),
                connected: false,
                modk: None,
                supermod: None,
            },
        ];
        let ServerMsg::PlayerList(Some(PV::Array(l))) = sm(player_list(&entries)) else { panic!() };
        assert_eq!(l.items.len(), 2);
        assert_eq!(l.items[0].object_for_key("supermod").unwrap().as_str(), Some("mode1"));
        assert!(l.items[1].object_for_key("photo").is_none());
        let chat = server_chat_dict("hi", "Al", "p1", 5.0);
        let ServerMsg::Chat(Some(c)) = sm(chat_message(&chat)) else { panic!() };
        assert_eq!(c.object_for_key("message").unwrap().as_str(), Some("hi"));
        let ServerMsg::ChatHistory(Some(h)) = sm(chat_history(&PV::array(vec![]), &[chat.clone()])) else { panic!() };
        assert!(h.object_for_key("messages").is_some());
        assert!(matches!(sm(admin_or_mod_changed(1, 0)), ServerMsg::AdminOrModChanged { x: 1, y: 0 }));
        assert!(matches!(sm(clear_chat()), ServerMsg::ClearChat));
        assert!(matches!(sm(toggle_repair_mode(true)), ServerMsg::ToggleRepairMode(true)));
        assert!(matches!(sm(toggle_repair_mode(false)), ServerMsg::ToggleRepairMode(false)));
        let summary = world_summary(&WorldSummary {
            owner: true,
            privacy: Some(2),
            server_password: Some("pw".into()),
            admin: true,
            moderator: true,
            supermod: Some(1),
            disable_pvp: true,
            world_price_multipliers: Some(PV::array(vec![])),
            welcome_message: Some("hello".into()),
            ownership_sign_positions: Some(PV::array(vec![])),
            custom_rules: Some(dict_of(vec![])),
            ..Default::default()
        });
        let ServerMsg::Summary(Some(s)) = sm(summary) else { panic!() };
        assert!(WorldSummary::default().to_plist().object_for_key("owner").is_none());
        let no_pw = WorldSummary { owner: true, privacy: Some(1), ..Default::default() }.to_plist();
        assert!(no_pw.object_for_key("privacy").is_some() && no_pw.object_for_key("serverPassword").is_none());
        for k in [
            "owner",
            "privacy",
            "serverPassword",
            "admin",
            "mod",
            "supermod",
            "disablePvp",
            "worldPriceMultipliers",
            "welcomeMessage",
            "ownershipSignPositions",
            "customRules",
        ] {
            assert!(s.object_for_key(k).is_some(), "{k}");
        }
        let bare = WorldSummary { owner: true, ..Default::default() }.to_plist();
        assert!(bare.object_for_key("privacy").is_none() && bare.object_for_key("minorVersion").is_some());
        let mut food = [0i32; 31];
        food[3] = 9;
        let reply = sm(initial_data_reply(&food, Some(b"<?xml version=\"1.0\"?><plist><dict/></plist>")));
        let ServerMsg::InitialData { food_types, plist } = reply else { unreachable!() };
        assert_eq!((food_types[3], plist.is_some()), (9, true));
        assert!(matches!(sm(initial_data_reply(&food, None)), ServerMsg::InitialData { plist: None, .. }));
        assert!(matches!(sm(unique_id_reply(77)), ServerMsg::UniqueId(77)));
        let ServerMsg::PickupReply { accepted, requester, ids } = sm(pickup_reply(true, 5, &[1, 2])) else { panic!() };
        assert_eq!((accepted, requester, ids), (true, 5, vec![1, 2]));
        assert!(matches!(sm(zoom_response(Some((3, 4)))), ServerMsg::ZoomResponse(Some((3, 4)))));
        assert!(matches!(sm(zoom_response(None)), ServerMsg::ZoomResponse(None)));
        let welcome = sm(welcome_message(Some(&PV::string("hi")), Some(&dict_of(vec![]))));
        let ServerMsg::Welcome(Some(w)) = welcome else { panic!() };
        assert!(w.object_for_key("welcomeMessage").is_some() && w.object_for_key("customRules").is_some());
        assert!(matches!(sm(welcome_message(None, None)), ServerMsg::Welcome(Some(_))));
        let list = PV::array(vec![dict_of(vec![("name", PV::string("n")), ("id", PV::string("i"))])]);
        assert!(matches!(sm(ownership_sign_player_list(&list)), ServerMsg::OwnershipSignPlayerList(Some(_))));
        assert!(matches!(
            sm(ownership_sign_modified(&dict_of(vec![("k", PV::int(1))]))),
            ServerMsg::OwnershipSignModified(Some(_))
        ));
        assert!(matches!(sm(price_offsets(&dict_of(vec![]))), ServerMsg::PriceOffsets(Some(_))));
        let ServerMsg::PortalChestAck { raw8, id } = sm(portal_chest_ack(0x0102)) else { panic!() };
        assert_eq!((id, raw8[0]), (0x0102, 2));
        let resent = sm(portal_chest_ack_resend(&[7, 0, 1, 2, 3, 4, 5, 6]));
        let ServerMsg::PortalChestAck { id, .. } = resent else { panic!() };
        assert_eq!(id, 7);
        let unsaved = sm(portal_chest_not_saved(&[9, 1, 0, 0, 0, 0, 0, 0]));
        let ServerMsg::PortalChestNotSaved { raw8, id } = unsaved else { panic!() };
        assert_eq!((id, raw8[1]), (0x0109, 1));
        let ServerMsg::PortalChestAck { id, .. } = sm(vec![t::SERVER_PORTAL_CHEST_ACK, 5]) else { panic!() };
        assert_eq!(id, 5);
        let ServerMsg::PaintingData { id, image } = sm(painting_data(3, &[1, 2, 3])) else { panic!() };
        assert_eq!((id, image), (3, vec![1, 2, 3]));
        let ServerMsg::ChestInventory { id, inventory } = sm(chest_inventory(4, Some(&[5]))) else { panic!() };
        assert_eq!((id, inventory), (4, vec![5]));
        let ServerMsg::ChestInventory { inventory, .. } = sm(chest_inventory(4, None)) else { panic!() };
        assert!(inventory.is_empty());
        let ServerMsg::Heartbeat(hb) = sm(heartbeat(&WorldHeartbeat::default())) else { panic!() };
        assert_eq!(hb.to_vec().len(), 16);
        assert!(matches!(sm(gather_notification(&GatherNetRequest::default())), ServerMsg::Gather(_)));
        assert!(matches!(sm(projectile(&ProjectileNetRequest::default())), ServerMsg::Projectile(_)));
        assert!(matches!(sm(blockhead_damage(&BlockheadDamageNetRequest::default())), ServerMsg::Damage(_)));
        let ServerMsg::Tip(text) = sm(tip("hint")) else { panic!() };
        assert_eq!(text, "hint");
        // block messages
        let tiles = [3u8; TILES_LEN];
        let light = [4u8; LIGHT_LEN];
        let extra = ExtraData { hash: "h".into(), receipts: Some(vec![1, 2]) };
        let pk = server_block_from_parts(9, &tiles, 2, 5, Some((&light, &extra))).unwrap();
        let ServerMsg::Block(b) = sm(pk) else { panic!() };
        assert_eq!((b.macro_index, b.version, b.update_index, b.light[0]), (9, 2, 5, 4));
        let pk = server_block_from_parts(9, &tiles, 2, 5, None).unwrap();
        let ServerMsg::Block(b) = sm(pk) else { panic!() };
        assert!(b.extra.is_none() && b.light.iter().all(|x| *x == 0));
        assert!(matches!(sm(block_not_loaded(5)), ServerMsg::BlockNotLoaded { index: 5, index32: 5 }));
        let ServerMsg::LightBlock(lb) = sm(light_block(7, &light, 3)) else { panic!() };
        assert_eq!((lb.macro_index, lb.update_index), (7, 3));
        let batch = encode_batch(BatchKind::Update, 4, &[vec![1; 9]]).unwrap();
        assert!(matches!(sm(batch), ServerMsg::Batch(_)));
        // malformed forms fall back to Unknown, empty packets are ignored, short structs are zero filled
        assert!(matches!(sm(vec![t::SERVER_BLOCK, 1, 2]), ServerMsg::Unknown { .. }));
        assert!(matches!(sm(vec![t::SERVER_BLOCK_NOT_LOADED, 1]), ServerMsg::Unknown { .. }));
        assert!(matches!(sm(vec![t::SERVER_LIGHT_BLOCK, 1, 2, 3, 4, 9]), ServerMsg::Unknown { .. }));
        assert!(matches!(sm(vec![t::SERVER_DYNAMIC_OBJECT_CREATE, 1, 2, 3]), ServerMsg::Unknown { .. }));
        assert!(matches!(sm(vec![0xee, 1]), ServerMsg::Unknown { ty: 0xee, .. }));
        assert!(matches!(decode_server_packet(&[]), Err(Malformed::Ignore)));
        assert!(decode_server_packet(&[t::SERVER_DYNAMIC_OBJECT_CREATE]).is_err());
        let ServerMsg::PickupReply { ids, .. } = sm(vec![t::SERVER_PICKUP_REPLY]) else { panic!() };
        assert!(ids.is_empty());
        assert!(electricity_path(1, &[ElectricityPathIndex::default()]).is_some());
    }

    #[test]
    fn client_packets_round_trip_through_the_decoder() {
        let cm = |p: Vec<u8>| decode_client_packet(&p).unwrap().unwrap();
        assert!(
            matches!(cm(block_request(ClientMacroBlockRequest { macro_index: 4, ..Default::default() })), ClientMsg::BlockRequest(r) if r.macro_index == 4)
        );
        assert!(matches!(cm(block_removal_notification(9)), ClientMsg::BlockRemovalNotification { macro_index: 9 }));
        for (ty, want) in [
            (t::CLIENT_INITIAL_DATA_REQUEST, "InitialDataRequest"),
            (t::CLIENT_UNIQUE_ID_REQUEST, "UniqueIdRequest"),
            (t::CLIENT_WORLD_HEARTBEAT_REQUEST, "HeartbeatRequestOld"),
            (t::CLIENT_WELCOME_MESSAGE_GET_REQUEST, "WelcomeMessageGet"),
            (t::CLIENT_OWNERSHIP_SIGN_PLAYER_LIST_REQUEST, "OwnershipSignPlayerListRequest"),
        ] {
            assert_eq!(format!("{:?}", cm(vec![ty])), want);
        }
        for ty in [
            t::CLIENT_DYNAMIC_OBJECT_CREATE,
            t::CLIENT_DYNAMIC_OBJECT_UPDATE,
            t::CLIENT_DYNAMIC_OBJECT_REMOVE,
            t::CLIENT_DYNAMIC_OBJECT_CREATION_DATA_UPDATE,
        ] {
            let m = cm(client_gz_plist(ty, &PV::array(vec![]))
                .into_iter()
                .take(1)
                .chain([6])
                .chain(crate::protocol::codec::gz(b"x"))
                .collect());
            assert!(format!("{m:?}").contains("ty: 6"));
        }
        for ty in [
            t::CLIENT_FILL_REQUEST,
            t::CLIENT_REMOVE_REQUEST,
            t::CLIENT_REMOVE_BACK_WALL_REQUEST,
            t::CLIENT_FREEBLOCK_CREATION_REQUEST,
            t::CLIENT_PAINT_REQUEST,
            t::CLIENT_BLOCKHEAD_DAMAGE_REQUEST,
            t::CLIENT_BLOCKHEADS,
            t::CLIENT_PLAYER_INFORMATION,
            t::CLIENT_WORLD_HEARTBEAT_REQUEST_WITH_CUSTOM_RULES,
            t::SERVER_WORLD_HEARTBEAT,
            t::CLIENT_FOUND_ITEM_LIST_CHANGED_OLD,
        ] {
            let m = cm(vec![ty, 1, 2, 3]);
            assert!(format!("{m:?}").contains("payload: [1, 2, 3]"), "{ty:#x}");
        }
        assert!(matches!(cm(vec![t::CLIENT_PLACE_WORKBENCH_REQUEST; 17]), ClientMsg::PlaceWorkbench { .. }));
        assert!(matches!(
            cm(vec![t::CLIENT_PLACE_INTERACTION_OBJECT_REQUEST; 9]),
            ClientMsg::PlaceInteractionObject { .. }
        ));
        assert!(matches!(cm(vec![t::GATHER_NOTIFICATION, 1]), ClientMsg::Gather { .. }));
        assert!(matches!(cm(vec![t::CLIENT_PROJECTILE_REQUEST, 1]), ClientMsg::Projectile { .. }));
        assert!(matches!(cm(vec![t::TIP_NOTIFICATION, 1]), ClientMsg::Tip { .. }));
        assert!(matches!(
            cm(electricity_path(1, &[ElectricityPathIndex::default()]).unwrap()),
            ClientMsg::ElectricityPath { .. }
        ));
        let ClientMsg::ZoomRequest { player_id, cycle_index } = cm(zoom_request("pid", 3)) else { panic!() };
        assert_eq!((player_id.as_deref(), cycle_index), (Some("pid"), 3));
        let d = dict_of(vec![("a", PV::int(1))]);
        assert!(matches!(cm(client_chat(&d)), ClientMsg::Chat { dict: Some(_) }));
        assert!(matches!(cm(client_player_information(&d)), ClientMsg::PlayerInformation { .. }));
        assert!(matches!(cm(client_heartbeat(&WorldHeartbeat::default())), ClientMsg::Heartbeat { .. }));
        assert!(
            matches!(cm(client_xml_plist(t::CLIENT_PASSWORD_CHANGE_REQUEST, &dict_of(vec![("newServerPassword", PV::string("np"))]))), ClientMsg::PasswordChange { new_password: Some(ref p) } if p == "np")
        );
        assert!(matches!(
            cm(vec![t::CLIENT_PASSWORD_CHANGE_REQUEST]),
            ClientMsg::PasswordChange { new_password: None }
        ));
        assert!(matches!(
            cm(client_xml_plist(t::CLIENT_PRIVACY_CHANGE_REQUEST, &dict_of(vec![("privacySetting", PV::string("2"))]))),
            ClientMsg::PrivacyChange { privacy: Some(_) }
        ));
        assert!(matches!(cm(vec![t::CLIENT_PRIVACY_CHANGE_REQUEST]), ClientMsg::PrivacyChange { privacy: None }));
        for (ty, want) in [
            (t::CLIENT_TRADE_TRANSACTION, "TradeTransaction"),
            (t::CLIENT_WELCOME_MESSAGE_SET_REQUEST, "WelcomeMessageSet"),
            (t::CLIENT_REPORT_USER, "ReportUser"),
            (t::CLIENT_UPDATE_CUSTOM_RULE, "UpdateCustomRule"),
        ] {
            assert!(format!("{:?}", cm(client_gz_plist(ty, &d))).starts_with(want), "{want}");
        }
        assert!(matches!(
            cm(vec![t::CLIENT_REQUEST_PAINTING_DATA, 9, 0, 0, 0, 0, 0, 0, 0]),
            ClientMsg::PaintingDataRequest { id: 9 }
        ));
        assert!(matches!(
            cm(vec![t::CLIENT_PORTAL_CHEST_TRANSACTION, 3, 0, 0, 0, 0, 0, 0, 0]),
            ClientMsg::PortalChestTransaction { id: 3, .. }
        ));
        assert!(matches!(
            cm(vec![t::CLIENT_PORTAL_CHEST_TRANSACTION_RESEND, 4, 0, 0, 0, 0, 0, 0, 0]),
            ClientMsg::PortalChestTransactionResend { id: 4, .. }
        ));
        let mut rm = vec![t::CLIENT_DYNAMIC_OBJECT_REMOVAL_REQUEST];
        rm.extend_from_slice(&5u64.to_le_bytes());
        rm.extend_from_slice(&6u64.to_le_bytes());
        assert!(matches!(cm(rm), ClientMsg::DynamicObjectRemovalRequest { blockhead_id: 5, object_id: 6 }));
        assert!(matches!(
            cm(vec![t::CLIENT_REPAIR_TILE, 7, 0, 0, 0, 0, 0, 0, 0]),
            ClientMsg::RepairTile { world_index: 7 }
        ));
        let fill = FillNetRequest::default();
        assert!(fill_request(&fill, None).len() == 17 && fill_request(&fill, Some(&d)).len() > 17);
        assert_eq!(client_struct(0x10, &fill).len(), 17);
        assert!(decode_client_packet(&[]).unwrap().is_none());
        assert_eq!(decode_strict::<FillNetRequest>(&[1]).map(|_| ()), None);
        assert!(decode_strict::<FillNetRequest>(&[0; 16]).is_some());
        assert!(decode_client_packet(&[t::CLIENT_PLACE_WORKBENCH_REQUEST, 1]).is_err());
    }
}

